def calculate_totals(items: list[dict[str, float]]) -> float:
    return sum(item['price'] for item in items)

cart: list[dict[str, float]] = [{'price': 19.99}, {'price': 5.50}]
print(f'Total: ${calculate_totals(cart):.2f}')

def find_user_id(email: str, users: dict[str, int]) -> int | None:
    return users.get(email)

registry: dict[str, int] = {'alice@corp.test': 101}
uid = find_user_id('bob@corp.test', registry)
if uid is not None:
    print(f'Found: {uid}')
else:
    print('User not found')

from typing import Protocol

class Renderable(Protocol):
    def render(self) -> str:
        ...

class UserCard:
    def __init__(self, name: str):
        self.name = name
    def render(self) -> str:
        return f'<div>{self.name}</div>'

def display(widget: Renderable) -> str:
    return widget.render()

print(display(UserCard('Ada')))
